def _settle_stderr():
    """Flush stderr; if that fails, silence it so the exit status survives."""
    try:
        sys.stderr.flush()
    except (OSError, ValueError, AttributeError):
        _silence_stream(sys.stderr)


_HELP_FLAGS = ("-h", "--help")
_VALUE_OPTIONS = ("--by", "--category", "--since", "--until", "--format")


def _is_option(arg):
    """True for a word `add` must leave to argparse: help, or an unknown ``--long`` option."""
    return arg in _HELP_FLAGS or (arg.startswith("--") and len(arg) > 2)


def _protect_add(argv):
    """Put ``--`` before the positionals of ``add`` so values starting with ``-`` are kept.

    ``add`` takes no options besides help, so a DATE, CATEGORY, AMOUNT or NOTE that starts
    with a single ``-`` (``-1,000.00``, ``-food``) is data, and the entry parser judges it.
    Help and ``--long`` words given before the fourth positional stay options.
    """
    if "--" in argv:
        return argv
    seen = 0
    last_option = 0
    for index in range(1, len(argv)):
        if _is_option(argv[index]):
            last_option = index
        else:
            seen += 1
            if seen == 4:
                break
    return argv[: last_option + 1] + ["--"] + argv[last_option + 1 :]


def _protect_file(argv):
    """Let a read command take a FILE starting with a single ``-`` (``balance -x``).

    Such a word is moved behind ``--`` at the end, so options may still follow or precede it.
    """
    if "--" in argv:
        return argv
    keep, moved = [argv[0]], []
    for index in range(1, len(argv)):
        arg = argv[index]
        value_of_option = argv[index - 1] in _VALUE_OPTIONS
        if arg.startswith("-") and not arg.startswith("--") and arg != "-" and arg != "-h" and not value_of_option:
            moved.append(arg)
        else:
            keep.append(arg)
    return keep + ["--"] + moved if moved else argv


def _protect_dashes(argv):
    argv = list(argv)
    if not argv:
        return argv
    if argv[0] == "add":
        return _protect_add(argv)
    if argv[0] in ("balance", "summary", "list", "export"):
        return _protect_file(argv)
    return argv


def main(argv=None):
    """Run the CLI; return the process exit status."""
    parser, subparsers = _build_parser()
    if argv is None:
        argv = sys.argv[1:]
    try:
        args, extras = parser.parse_known_args(_protect_dashes(argv))
        if extras:
            # Name the subcommand's own usage, not the top-level one.
            subparsers.get(args.command, parser).error("unrecognized arguments: %s" % " ".join(extras))
    except SystemExit as exc:
        _settle_stderr()
        return exc.code if isinstance(exc.code, int) else EXIT_USAGE
    if sys.stdout is None:
        # Fail before `add` appends an entry whose confirmation cannot be shown.
        _complain("cannot write to standard output: it is closed")
        return EXIT_USAGE
    try:
        output = _COMMANDS[args.command](args)
    except _LedgerError as exc:
        _complain(exc)
        return EXIT_LEDGER
    except OSError as exc:
        _complain(exc)
        return EXIT_USAGE
    try:
        sys.stdout.write(output)
        sys.stdout.flush()
    except BrokenPipeError:
        # The reader closed the pipe early (e.g. `| head -1`). Point stdout at
        # the null device so the interpreter's final flush cannot fail too.
        _silence_stdout()
        return EXIT_OK
    except (OSError, ValueError, AttributeError) as exc:
        # Full disk, closed descriptor, closed file object, ...
        _silence_stdout()
        _complain("cannot write to standard output: %s" % _reason(exc))
        return EXIT_USAGE
    return EXIT_OK

